create index idx_ai_sys_cross_border on gov_repo.ai_systems(organisation_id) where is_cross_border=true;
create index idx_ai_sys_tags on gov_repo.ai_systems using gin(tags);
create index idx_ai_sys_capabilities on gov_repo.ai_systems using gin(capabilities);
create index idx_ai_sys_harmonised_standards on gov_repo.ai_systems using gin(harmonised_standards) where harmonised_standards is not null;
create index idx_ai_sys_deployment_regions on gov_repo.ai_systems using gin(deployment_regions);
create index idx_ai_sys_residual_risk on gov_repo.ai_systems(residual_risk_level) where residual_risk_level in ('critical','high');
create index idx_ai_sys_conformity_expiry on gov_repo.ai_systems(conformity_valid_until) where conformity_valid_until is not null;
create index idx_ai_sys_iso42001_cert_expiry on gov_repo.ai_systems(iso_42001_cert_expires) where iso_42001_certified=true;
create or replace function gov_repo.update_ai_system_compliance_flags() returns trigger language plpgsql as $$ begin
 new.cg_sys_001_registered := (new.system_code is not null and new.name is not null and new.description is not null and new.intended_purpose is not null and new.organisation_id is not null);
 new.cg_sys_002_owner := (new.owner_user_id is not null);
 new.cg_sys_003_risk_classified := (new.risk_class is not null and new.annex_iii_sector is not null and (new.annex_iii_sector='not_annex_iii' or new.risk_class='high' or new.annex_iii_exception_claimed=true));
 new.cg_sys_004_tech_doc := (new.intended_purpose is not null and new.architecture_description is not null and new.training_methodology is not null and new.known_limitations is not null and (new.risk_class!='high' or new.technical_doc_evidence_id is not null));
 new.cg_sys_005_risk_mgmt := (new.risk_mgmt_system_desc is not null and new.risk_mgmt_last_review is not null and new.residual_risk_accepted_by is not null);
 new.cg_sys_006_human_oversight := (new.oversight_measures_desc is not null and new.override_mechanism_desc is not null and new.halt_mechanism_desc is not null and new.oversight_person_id is not null);
 new.cg_sys_007_conformity := (new.risk_class!='high' or (new.conformity_assessment_id is not null and new.ce_marking_status in ('marked') and new.doc_ref is not null));
 new.cg_sys_008_post_market := (new.lifecycle not in ('production','post_market_surveillance') or (new.pms_plan_documented=true and new.pms_plan_evidence_id is not null)); return new; end; $$;
create trigger trg_ai_sys_compliance_flags before insert or update on gov_repo.ai_systems for each row execute function gov_repo.update_ai_system_compliance_flags();
create policy "Authenticated read ai_systems" on gov_repo.ai_systems for select to authenticated using(organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1));
drop view if exists gov_repo.v_ai_systems_inventory;
create or replace view gov_repo.v_ai_systems_inventory as select s.organisation_id,s.system_id,s.system_code,s.name as system_name,s.version,s.lifecycle,s.status,s.risk_class,s.annex_iii_sector,s.gpai_tier,s.organisation_role,s.ce_marking_status,s.eu_ai_db_registered,s.eu_ai_db_ref,s.deployment_env,s.deployment_regions,s.is_cross_border,s.business_domain,s.industry_sector,u_owner.full_name as owner_name,u_owner.email as owner_email,u_tech.full_name as technical_owner_name,u_officer.full_name as ai_officer_name,(select count(*) from gov_repo.agents a where a.ai_system_id=s.system_id and a.status not in ('decommissioned')) as active_agent_count,(select count(*) from gov_repo.agents a where a.ai_system_id=s.system_id and a.risk_level in ('critical','high') and a.status not in ('decommissioned')) as high_risk_agent_count,(s.cg_sys_001_registered::int+s.cg_sys_002_owner::int+s.cg_sys_003_risk_classified::int+s.cg_sys_004_tech_doc::int+s.cg_sys_005_risk_mgmt::int+s.cg_sys_006_human_oversight::int+s.cg_sys_007_conformity::int+s.cg_sys_008_post_market::int) as compliance_score,(8-(s.cg_sys_001_registered::int+s.cg_sys_002_owner::int+s.cg_sys_003_risk_classified::int+s.cg_sys_004_tech_doc::int+s.cg_sys_005_risk_mgmt::int+s.cg_sys_006_human_oversight::int+s.cg_sys_007_conformity::int+s.cg_sys_008_post_market::int)) as total_gaps,s.pms_next_review,(s.pms_next_review<current_date and s.pms_plan_documented=true) as pms_overdue,s.conformity_valid_until,(s.conformity_valid_until<current_date and s.conformity_valid_until is not null) as conformity_expired,s.created_at,s.updated_at from gov_repo.ai_systems s left join gov_repo.governance_users u_owner on u_owner.user_id=s.owner_user_id left join gov_repo.governance_users u_tech on u_tech.user_id=s.technical_owner_id left join gov_repo.governance_users u_officer on u_officer.user_id=s.ai_officer_id where s.status!='decommissioned';;
